class Solution {
public:
    int trap(vector<int>& a) {
        int n=a.size();
        int k=n;
        for(int i=0;i<n-1;i++){
            if(a[i]!=0&&a[i+1]<a[i]){
                k=i;
                break;
            }
        }
        int ans=0,temp=0;
        for(int i=k+1;i<n;i++){
           if(a[i]>=a[k]){
               ans+=temp;
               temp=0;
               k=i;
           }
            else{
                temp+=a[k]-a[i];
            }
        }
        int p=k;
        for(int i=n-1;i>k;i--){
            if(a[i]!=0&&a[i-1]<a[i]){
                p=i;
                break;
            }
        }
        int ans1=0,temp1=0;
        for(int i=p-1;i>=k;i--){
           if(a[i]>=a[p]){
               ans1+=temp1;
               temp1=0;
               p=i;
           }
            else{
                temp1+=a[p]-a[i];
            }
        }
        return ans+ans1;
    }
};

